import{_ as a,c as t,o as e,a6 as l,bc as i,be as o,bf as r,bg as s,bh as c,bi as h,bj as _,bk as d,bl as n}from"./chunks/framework.DQNfPlXe.js";const q=JSON.parse('{"title":"使用ChatBox构建本地知识库","description":"","frontmatter":{"date":"2025-08-13T00:00:00.000Z","title":"使用ChatBox构建本地知识库"},"headers":[],"relativePath":"work/使用ChatBox构建本地知识库.md","filePath":"work/使用ChatBox构建本地知识库.md","lastUpdated":1755066998000}'),m={name:"work/使用ChatBox构建本地知识库.md"},p=l('<h1 id="使用chatbox构建本地知识库" tabindex="-1">使用ChatBox构建本地知识库 <a class="header-anchor" href="#使用chatbox构建本地知识库" aria-label="Permalink to &quot;使用ChatBox构建本地知识库&quot;">​</a></h1><h2 id="配置chatbox" tabindex="-1">配置ChatBox <a class="header-anchor" href="#配置chatbox" aria-label="Permalink to &quot;配置ChatBox&quot;">​</a></h2><p>根据 <a href="/work/使用ChatBox和AI对话.html">使用ChatBox和AI对话</a> 页面配置好ChatBox</p><h2 id="内嵌向量化模型" tabindex="-1">内嵌向量化模型 <a class="header-anchor" href="#内嵌向量化模型" aria-label="Permalink to &quot;内嵌向量化模型&quot;">​</a></h2><p>构建知识库需要使用向量模型将文本转换成LLM模型可以识别的向量。</p><p>市面上的大部分教程都是推荐使用Ollama搭一个本地的LLM环境并拉取向量化模型实现该功能。但这几乎没法在一些配置较低的电脑上运行（或者运行很慢）。所以我们仍需要在网络上寻找模型运营商来解决这个问题。</p><p>由于DeepSeek官方并未提供内嵌向量化模型。所以需要去别的运营商那里寻找答案。</p><p>在搜索了各个运营商后，我发现硅基流动(SiliconFlow)公司提供的<code>bge-m3</code>模型符合需求，且该模型免费。</p><p>以下教程皆使用硅基流动的向量模型编写并测试通过。</p><h2 id="获取硅基流动api-key" tabindex="-1">获取硅基流动API Key <a class="header-anchor" href="#获取硅基流动api-key" aria-label="Permalink to &quot;获取硅基流动API Key&quot;">​</a></h2><ul><li>注册硅基流动账户： <a href="https://cloud.siliconflow.cn/i/nUhBTwBg" target="_blank" rel="noreferrer">硅基流动注册页面</a></li><li>然后应该会跳转到模型广场，如果没有跳转，则可以使用这个 <a href="https://cloud.siliconflow.cn/me/models" target="_blank" rel="noreferrer">链接</a></li><li>点击左侧<code>API密钥</code>，与DeepSeek类似，我们需要在硅基流动中获取一个密钥。</li><li>在ChatBox中的设置的模型设置中选择硅基流动，填写获取的密钥 <img src="'+i+'" alt="alt text"></li></ul><details class="details custom-block"><summary>可选：设置视觉内嵌模型</summary><ul><li>点击模型的新建按钮，在弹出框中输入模型名称<code>THUDM/GLM-4.1V-9B-Thinking</code>，这是一个免费的视觉向量模型</li><li>勾选能力中的视觉，保存。</li><li><img src="'+o+'" alt="alt text"></li><li><img src="'+r+'" alt="alt text"></li></ul></details><h2 id="配置本地知识库" tabindex="-1">配置本地知识库 <a class="header-anchor" href="#配置本地知识库" aria-label="Permalink to &quot;配置本地知识库&quot;">​</a></h2><ul><li>点击设置中的知识库</li><li>点击<code>创建首个知识库</code><img src="'+s+'" alt="alt text"></li><li>设置知识库的名称、内嵌向量模型、重排模型、视觉模型(可选)，点击创建 <img src="'+c+'" alt="alt text"></li><li>在创建好的知识库里点击上传文件，点击文本上传框或直接将文件拖入，即可开始上传。等待上传完成。 <img src="'+h+'" alt="alt text"></li><li>上传完成后，文件右侧会显示一个绿色上传成功图标，如果出现失败，可尝试重传，或检查模型配置。 <img src="'+_+'" alt="alt text"></li><li>藉此你已经完成了第一个本地知识库的创建。</li></ul><h2 id="使用知识库对话" tabindex="-1">使用知识库对话 <a class="header-anchor" href="#使用知识库对话" aria-label="Permalink to &quot;使用知识库对话&quot;">​</a></h2><ul><li>我在上一步将当前网站的独立游戏相关的文档添加进知识库中，以下使用这个知识库作为模型回答的依据。</li><li>点击新的对话。点击本地知识库按钮，选择刚完成配置的本地知识库。</li><li>提问：<code>什么是Godot？使用知识库内容进行回答</code>，ChatBox会调用DeepSeek回答问题，中途需要调用知识库时会自动请求知识库的内容。 <img src="'+d+'" alt="alt text"></li><li>成功根据博客内容作答。 <img src="'+n+'" alt="alt text"></li></ul>',16),x=[p];function u(b,f,k,B,C,g){return e(),t("div",null,x)}const T=a(m,[["render",u]]);export{q as __pageData,T as default};
